// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 guessValue) public {
        vm.assume(actor != address(0));

        vm.deal(actor, 2 ether);
        bytes32 secret = keccak256(abi.encodePacked(guessValue, actor));
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(secret);

        // Mine the guess block: block.number + 1, then advance past it
        vm.roll(block.number + 2);

        bytes32 answer = blockhash(block.number - 1);

        // Only proceed if the hash is non-zero and the secret is not the answer
        vm.assume(answer != bytes32(0));
        vm.assume(answer != secret);

        vm.prank(actor);
        c.settle();

        // After settle, the guess should be reset, so a second settle must revert
        vm.prank(actor);
        bool secondSettleOk = _trySettle(actor);

        assertTrue(!secondSettleOk);
    }

    function _trySettle(address actor) internal returns (bool ok) {
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
    }
}
